{
  "implementation": "def solve(case):
    required_keys = ['passing', 'failing', 'required_difference', 'unresolved_difference']
    for key in required_keys:
        if key not in case:
            raise ValueError(f'Missing field: {key}')
    passing = case['passing']
    failing = case['failing']
    required_diff = case['required_difference']
    unresolved_diff = case['unresolved_difference']
    diff = []
    for elem in failing:
        if elem not in passing:
            diff.append(elem)
    def predicate(subset):
        set_subset = set(subset)
        for u in unresolved_diff:
            if u in set_subset:
                return 'UNRESOLVED'
        for r in required_diff:
            if r not in set_subset:
                return 'PASS'
        return 'FAIL'
    call_count = [0]
    def counted_predicate(subset):
        call_count[0] += 1
        return predicate(subset)
    def split(s, n):
        k, m = divmod(len(s), n)
        subsets = []
        start = 0
        for i in range(n):
            size = k + (1 if i < m else 0)
            subsets.append(s[start:start+size])
            start += size
        return subsets
    def ddmin(cs, pred):
        pred(cs)
        if not cs:
            return []
        n = 2
        while len(cs) >= 2:
            subsets = split(cs, n)
            reduced = False
            for sub in subsets:
                complement = [x for x in cs if x not in sub]
                res = pred(complement)
                if res == 'FAIL':
                    cs = complement
                    n = max(n-1, 2)
                    reduced = True
                    break
                res = pred(sub)
                if res == 'FAIL':
                    cs = sub
                    n = 2
                    reduced = True
                    break
            if not reduced:
                n = min(n*2, len(cs))
        return cs
    isolated = ddmin(diff, counted_predicate)
    return {'isolated_difference': isolated, 'tests': call_count[0]}"
}
